import type { Vec2 } from "../math/vec2";
import type { Body } from "../dynamics/body";

/** A world-space contact point and its penetration depth (positive when overlapping). */
export type ContactPoint = { point: Vec2; depth: number };

/** The result of a collision: unit normal from A to B, and 1 or 2 contact points. */
export type Manifold = { a: Body; b: Body; normal: Vec2; points: ContactPoint[] };
